INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (1, 'Yale', 'yale', 'One of the world''s most trusted lock brands, offering smart locks with wide protocol support and HomeKit compatibility.', 'Yale, a division of ASSA ABLOY, has been a leader in lock manufacturing for over 180 years. Their smart lock lineup spans from budget-friendly Zigbee models to premium Wi-Fi-enabled deadbolts. Yale smart locks are known for their reliable build quality, broad protocol support (Zigbee, Z-Wave, Wi-Fi, Thread), and deep integration with Apple HomeKit and other smart home ecosystems. The Assure Lock 2 series represents their flagship offering with Matter/Thread future-proofing.', '/images/brands/yale-logo.png', 'https://www.yalehome.com/', 'US', 1840, 1, 1, 1, 1, 1, 1, 'residential', 'mid', 'Yale Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Comprehensive guide to Yale smart locks. Compare Assure Lock 2, Nest × Yale, and more. Protocol support, pricing, and expert recommendations.', NULL, 4.5, 1, 1, 'published', '2026-02-15 18:55:36', '2026-02-15 18:55:36');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (2, 'August', 'august', 'Pioneer of retrofit smart locks that work with your existing deadbolt. Easy installation, app-centric experience.', 'August, now part of ASSA ABLOY, revolutionized the smart lock market with their retrofit design that installs over your existing deadbolt in minutes. This means renters can upgrade without replacing hardware. August locks are app-centric, offering auto-unlock via geofencing, DoorSense technology, and guest access management. While they excel in convenience, their reliance on Wi-Fi (via bridge or built-in) means shorter battery life compared to Zigbee/Z-Wave alternatives. The August Wi-Fi Smart Lock (4th Gen) remains one of the most popular choices for renters and tech enthusiasts.', '/images/brands/august-logo.png', 'https://august.com/', 'US', 2013, 1, 1, 0, 0, 0, 1, 'residential', 'mid', 'August Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to August smart locks. Retrofit design, Wi-Fi connectivity, auto-unlock features. Compare models and find the best fit.', NULL, 4.3, 1, 2, 'published', '2026-02-15 18:55:36', '2026-02-15 18:55:36');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (3, 'Schlage', 'schlage', 'Commercial-grade smart locks with ANSI Grade 1 security. Trusted by security professionals worldwide.', 'Schlage has been a cornerstone of American lock manufacturing since 1920. Their smart locks stand out with ANSI/BHMA Grade 1 certification — the highest security rating available for residential locks. The Schlage Encode Plus was the first lock to support Apple Home Key, allowing iPhone and Apple Watch tap-to-unlock. Schlage locks are known for their tank-like build quality, long battery life (up to 24 months), and resistance to forced entry. They serve both residential and commercial markets, making them the top choice for security-conscious users and property managers.', '/images/brands/schlage-logo.png', 'https://www.schlage.com/', 'US', 1920, 1, 1, 1, 0, 0, 1, 'all', 'premium', 'Schlage Smart Locks — Complete Brand Guide & Product Reviews 2026', 'In-depth guide to Schlage smart locks. ANSI Grade 1 security, Apple Home Key support. Compare Encode Plus, Connect, and commercial models.', NULL, 4.6, 1, 3, 'published', '2026-02-15 18:55:36', '2026-02-15 18:55:36');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (4, 'Kwikset', 'kwikset', 'Budget-friendly smart locks with patented SmartKey re-key technology. Best value in the market.', 'Kwikset, a Spectrum Brands company, offers the most affordable entry into smart locks without sacrificing essential features. Their patented SmartKey Security technology allows you to re-key the lock yourself in seconds — no locksmith needed. The Halo series provides Wi-Fi connectivity with no hub required, while the SmartCode series offers Z-Wave and Zigbee options for smart home integration. Kwikset locks typically carry ANSI Grade 2 certification and are ideal for budget-conscious homeowners who want smart features without the premium price tag.', '/images/brands/kwikset-logo.png', 'https://www.kwikset.com/', 'US', 1946, 1, 1, 1, 0, 0, 1, 'residential', 'budget', 'Kwikset Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Kwikset smart locks. SmartKey re-key technology, budget-friendly pricing. Compare Halo, Premis, and SmartCode models.', NULL, 4.2, 1, 4, 'published', '2026-02-15 18:55:36', '2026-02-15 18:55:36');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (5, 'Aqara', 'aqara', 'Smart home ecosystem leader with affordable Zigbee/Thread locks and Apple HomeKit integration.', 'Aqara, a Lumi United Technology subsidiary, has rapidly grown from a Xiaomi ecosystem brand to a global smart home leader. Their smart locks stand out with compact industrial design, fingerprint readers, and deep Apple HomeKit integration via their affordable Zigbee hubs. The U100 was one of the first smart locks to support Apple Home Key via NFC. Aqara is aggressively adopting Thread and Matter protocols, positioning their products for future-proof smart home ecosystems. Their locks offer excellent value with premium features at mid-range pricing.', '/images/brands/aqara-logo.png', 'https://www.aqara.com/', 'CN', 2009, 0, 1, 0, 1, 1, 1, 'residential', 'mid', 'Aqara Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Comprehensive guide to Aqara smart locks. Thread/Matter support, Apple Home Key, fingerprint authentication. Compare U100, A100, D100 models.', NULL, 4.4, 1, 5, 'published', '2026-02-15 18:55:36', '2026-02-15 18:55:36');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (6, 'Level', 'level', 'Invisible smart lock design that looks like a traditional lock. Premium build with Thread/Matter support.', 'Level has redefined smart lock aesthetics by creating locks that are virtually invisible — they look and feel like traditional locks while packing full smart functionality inside. The Level Lock+ was among the first to support Thread and Matter protocols, making it one of the most future-proof options available. Level locks are designed in San Francisco and engineered for minimalists who want smart home convenience without the sci-fi appearance. Their compact form factor fits inside the door, maintaining the original lock''s exterior appearance. Premium pricing reflects the engineering achievement.', '/images/brands/level-logo.png', 'https://level.co/', 'US', 2018, 0, 0, 0, 1, 1, 1, 'residential', 'premium', 'Level Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Level smart locks. Invisible design, Thread/Matter support. Compare Level Lock+, Bolt, and Touch models.', NULL, 4.4, 1, 6, 'published', '2026-02-15 18:55:36', '2026-02-15 18:55:36');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (7, 'Ultraloq', 'ultraloq', 'ANSI Grade 1 smart locks with 6-in-1 keyless entry. Multiple CES Innovation Award winner.', 'Ultraloq, made by U-Tec, has been a pioneer in multi-access smart locks for over 10 years with over 1 million locks sold. Their flagship U-Bolt Pro WiFi offers ANSI Grade 1 security with 6 ways to unlock: fingerprint, smartphone, auto-unlock, knock-to-open, keypad, and physical key. Ultraloq locks consistently earn top marks from PCMag, CNET, and Tom''s Guide. The Bolt Fingerprint series was the first to combine Matter protocol with fingerprint access. Their Latch 5 series brings smart lock technology to lever handle doors, expanding beyond deadbolts.', '/images/brands/ultraloq-logo.png', 'https://www.u-tec.com/', 'US', 2014, 1, 0, 1, 0, 1, 1, 'residential', 'mid', 'Ultraloq Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Comprehensive guide to Ultraloq smart locks. ANSI Grade 1, 6-in-1 keyless entry, fingerprint + Matter. Compare U-Bolt Pro, Bolt Fingerprint, and Latch models.', NULL, 4.5, 1, 7, 'published', '2026-02-15 18:55:45', '2026-02-15 18:55:45');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (8, 'Lockly', 'lockly', 'Patented PIN Genie anti-peep keypad and advanced biometric smart locks with facial recognition.', 'Lockly has carved a unique niche in the smart lock market with its patented PIN Genie technology — a rotating digital keypad that randomizes number positions with every use, making it impossible for onlookers to memorize your code. Beyond security innovation, Lockly has pushed into cutting-edge biometrics with the Visage Zeno series featuring 3D facial recognition, and the Vision Zeno series integrating a video doorbell directly into the lock. Lockly locks are trusted by both homeowners and Airbnb hosts for their robust security and remote management capabilities via the Lockly app.', '/images/brands/lockly-logo.png', 'https://lockly.com/', 'US', 2019, 1, 0, 0, 0, 0, 1, 'all', 'mid', 'Lockly Smart Locks — Complete Brand Guide & Product Reviews 2026', 'In-depth guide to Lockly smart locks. Patented PIN Genie anti-peep keypad, facial recognition, video doorbell locks. Compare Secure Pro, Vision, and Visage models.', NULL, 4.3, 1, 8, 'published', '2026-02-15 18:55:45', '2026-02-15 18:55:45');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (9, 'Eufy', 'eufy', 'Palm vein recognition and video smart locks from Anker. BHMA Grade 1 security with local storage.', 'Eufy, a subsidiary of Anker Innovations, has rapidly expanded from home security cameras into smart locks with their FamiLock lineup. Eufy stands out with palm vein recognition technology (PowerDuo) — a biometric method that reads the vein pattern beneath your palm for fast, hygienic, and highly secure access without touching the lock. Their Video Smart Lock series integrates 2K cameras with two-way audio directly into the deadbolt. Eufy emphasizes local storage and privacy-first design, processing biometric data on-device without cloud dependency. All flagship models carry BHMA Grade 1 certification.', '/images/brands/eufy-logo.png', 'https://www.eufy.com/', 'CN', 2016, 1, 0, 0, 0, 0, 1, 'residential', 'mid', 'Eufy Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Eufy FamiLock smart locks. Palm vein recognition, video doorbell locks, BHMA Grade 1. Compare S3 Max, E330, and C241 models.', NULL, 4.4, 1, 9, 'published', '2026-02-15 18:55:45', '2026-02-15 18:55:45');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (10, 'SwitchBot', 'switchbot', 'Retrofit smart locks with rechargeable battery and Matter support via hub. Affordable smart home ecosystem.', 'SwitchBot started as a smart home automation brand known for their ingenious Bot finger robot and has grown into a full ecosystem including smart locks. The SwitchBot Lock Ultra, unveiled at CES 2025, is a compact retrofit smart lock made from magnesium aluminum alloy that installs over your existing deadbolt in minutes — perfect for renters. It features a rechargeable lithium-ion battery lasting up to 9 months, triple power protection (main battery + backup CR123A + supercapacitor), and Matter support via SwitchBot Hub. With up to 16 ways to unlock including NFC, fingerprint (via keypad accessory), and facial recognition, SwitchBot offers exceptional value.', '/images/brands/switchbot-logo.png', 'https://www.switch-bot.com/', 'CN', 2015, 0, 0, 0, 0, 1, 1, 'residential', 'budget', 'SwitchBot Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to SwitchBot smart locks. Retrofit design, rechargeable battery, Matter support. Compare Lock Ultra and Lock Pro models.', NULL, 4.3, 1, 10, 'published', '2026-02-15 18:55:45', '2026-02-15 18:55:45');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (11, 'Wyze', 'wyze', 'Ultra-affordable smart locks with fingerprint and Wi-Fi. Best value in the smart lock market.', 'Wyze has built its reputation on delivering surprisingly capable smart home products at fraction-of-the-cost pricing, and their smart locks continue this tradition. The Wyze Lock Bolt v2 delivers fingerprint authentication, Wi-Fi remote access, and a full keypad for under $80 — dramatically undercutting competitors. Wyze locks are BHMA Grade 2 certified and powered by 8 AA batteries lasting up to 8 months. While they may lack premium features like Apple Home Key or Thread/Matter support, Wyze locks deliver the core smart lock experience — remote access, fingerprint unlock, guest codes, and activity logs — at an unbeatable price point.', '/images/brands/wyze-logo.png', 'https://www.wyze.com/', 'US', 2017, 1, 0, 0, 0, 0, 1, 'residential', 'budget', 'Wyze Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Wyze smart locks. Budget-friendly fingerprint + Wi-Fi locks under $80. BHMA Grade 2 security at the best value.', NULL, 4, 0, 11, 'published', '2026-02-15 18:55:45', '2026-02-15 18:55:45');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (12, 'Nuki', 'nuki', 'European retrofit smart locks with native Matter/Thread support. Auto-unlock and rechargeable design.', 'Nuki, headquartered in Graz, Austria, is the leading European smart lock brand. Their retrofit design mounts over existing Euro-profile cylinders, making installation tool-free and reversible — ideal for European renters. The Nuki Smart Lock Pro 4.0 was among the first locks to ship with native Matter over Thread support, enabling seamless integration across Apple Home, Google Home, and Amazon Alexa without proprietary hubs. Nuki''s standout feature is its precise auto-unlock via Bluetooth geofencing — the lock detects when you approach and unlocks automatically. The Pro model includes a rechargeable battery pack and built-in Wi-Fi for remote access.', '/images/brands/nuki-logo.png', 'https://nuki.io/', 'AT', 2014, 1, 0, 0, 1, 1, 1, 'residential', 'mid', 'Nuki Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Nuki smart locks. European retrofit design, native Matter/Thread, auto-unlock. Compare Smart Lock Pro 4.0 and Smart Lock 4.0.', NULL, 4.3, 1, 12, 'published', '2026-02-15 18:55:45', '2026-02-15 18:55:45');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (13, 'igloohome', 'igloohome', 'Offline-first smart locks with algoPIN technology. Built for Airbnb hosts and property managers.', 'igloohome, founded in Singapore, has pioneered offline-first smart lock technology with their proprietary algoPIN system. Unlike most smart locks that require Wi-Fi or Bluetooth for remote access, igloohome generates time-sensitive PIN codes algorithmically — meaning hosts can create and share access codes without any internet connection at the lock. This makes igloohome ideal for vacation rentals, construction sites, and remote properties with unreliable connectivity. Their locks are IP65 rated for weather resistance and integrate directly with Airbnb for automated guest check-in. The product range spans deadbolts, keyboxes, padlocks, and mortise locks.', '/images/brands/igloohome-logo.png', 'https://www.igloohome.co/', 'SG', 2015, 0, 0, 0, 0, 0, 1, 'all', 'mid', 'igloohome Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to igloohome smart locks. Offline algoPIN technology, Airbnb integration, IP65 weatherproof. Compare Deadbolt 2S, Deadbolt Go, and Keybox 3.', NULL, 4.1, 0, 13, 'published', '2026-02-15 18:55:45', '2026-02-15 18:55:45');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (14, 'Bosma', 'bosma', 'Video smart locks with facial recognition and built-in camera. Affordable biometric security.', 'Bosma is a US-based smart home brand that combines smart lock functionality with video surveillance in a single device. The Bosma Aegis features a built-in HD camera with facial recognition, allowing the lock to identify family members and unlock automatically while alerting you to strangers. Their locks offer traditional smart lock features — keypad, fingerprint, app control — plus the unique addition of video recording and two-way audio. Bosma targets budget-conscious homeowners who want both a smart lock and a video doorbell in one package, offering significant cost savings over buying separate devices.', '/images/brands/bosma-logo.png', 'https://www.bosma.co/', 'US', 2018, 1, 0, 0, 0, 0, 1, 'residential', 'budget', 'Bosma Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Bosma smart locks. Video doorbell + smart lock combo, facial recognition, HD camera. Compare Aegis and Sentry models.', NULL, 4, 0, 14, 'published', '2026-02-15 18:55:45', '2026-02-15 18:55:45');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (15, 'Samsung', 'samsung', 'Global electronics leader with premium fingerprint and NFC smart locks. Dominant in Asian markets.', 'Samsung, the South Korean technology giant, has been a pioneer in digital door locks since the mid-2000s, particularly dominating the Asian smart lock market. Samsung''s SHP series locks are known for enterprise-grade fingerprint sensors, NFC card access, and push-pull ergonomic handles — a design philosophy that has become the standard in Korean and Southeast Asian residential buildings. Their locks feature advanced anti-hack relay attack protection, random security codes, and Bluetooth connectivity via the Samsung Smart Home app. In some regions, Samsung''s digital lock division has transitioned to the Zigbang brand while maintaining the same engineering standards. Samsung locks consistently rank among the most durable in independent stress tests.', '/images/brands/samsung-logo.png', 'https://www.samsung.com/', 'KR', 1969, 1, 0, 0, 0, 0, 1, 'all', 'premium', 'Samsung Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Samsung digital door locks. SHP series with fingerprint, NFC card, push-pull handles. Premium Asian market leader.', NULL, 4.5, 1, 15, 'published', '2026-02-15 18:55:55', '2026-02-15 18:55:55');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (16, 'Philips', 'philips', '3D facial recognition and video smart locks with Wi-Fi. Robust mortise lock lineup for global markets.', 'Philips EasyKey brings the trusted Philips brand into smart home security with an impressive lineup of smart door locks featuring 3D facial recognition, video intercom, and built-in Wi-Fi. The DDL702 Alpha series leads with a structured light facial recognition module that can identify faces in under 0.3 seconds, even in complete darkness. Philips locks are primarily designed for Asian-standard mortise lock installations, featuring auto-locking motors that engage the deadbolt and latch simultaneously. With the Philips EasyKey App, users get remote monitoring, temporary PIN codes for visitors, real-time alerts, and video recording (on camera models). All models feature C-grade lock cylinders for high resistance against technical lock-picking.', '/images/brands/philips-logo.png', 'https://www.philips.com/', 'NL', 1891, 1, 0, 0, 0, 0, 1, 'residential', 'premium', 'Philips Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Philips EasyKey smart locks. 3D facial recognition, video intercom, Wi-Fi. DDL702 Alpha series review.', NULL, 4.4, 1, 16, 'published', '2026-02-15 18:55:55', '2026-02-15 18:55:55');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (17, 'Alfred', 'alfred', 'Canadian smart locks with Z-Wave Plus and Wi-Fi bridge options. Multi-connectivity modular design.', 'Alfred, a Canadian smart lock brand, has carved a distinct position with its modular connectivity approach — each lock starts with Bluetooth and can be upgraded with optional Z-Wave, Zigbee 3.0, or Wi-Fi bridge modules. The Alfred DB2-B touchscreen deadbolt features an illuminated 12-button keypad with visual PIN protection, while the premium ML2 mortise lock targets high-rise residential buildings with rechargeable Li-ion battery, 250 PIN codes, 250 RFID cards, and even optional wireless long-range power. Alfred locks meet residential high-rise fire and emergency egress codes, making them popular in Canadian and North American condo developments. Their Connect Wi-Fi Bridge enables Amazon Alexa and Google Assistant voice control.', '/images/brands/alfred-logo.png', 'https://www.alfredlocks.com/', 'CA', 2014, 1, 1, 1, 0, 0, 1, 'residential', 'mid', 'Alfred Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Alfred smart locks. Z-Wave, Zigbee, Wi-Fi modular connectivity. DB2-B deadbolt and ML2 mortise lock reviews.', NULL, 4.1, 0, 17, 'published', '2026-02-15 18:55:55', '2026-02-15 18:55:55');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (18, 'SimpliSafe', 'simplisafe', 'Smart lock integrated with SimpliSafe home security system. Wi-Fi enabled with separate PIN pad.', 'SimpliSafe, one of America''s most popular DIY home security systems, offers a smart lock designed to integrate seamlessly with their Gen 3 security platform. The SimpliSafe Smart Lock Series 2 retrofits over existing single-cylinder deadbolts and connects via Wi-Fi for remote locking/unlocking through the SimpliSafe app. It pairs with a separate wireless PIN Pad (powered by CR2450 batteries) for keyless entry. When armed in Away mode, locking the smart lock automatically arms the entire SimpliSafe security system — a level of integration that standalone smart locks cannot match. While it lacks fingerprint or Matter support, its strength lies in deep ecosystem integration with SimpliSafe cameras, sensors, and 24/7 professional monitoring.', '/images/brands/simplisafe-logo.png', 'https://simplisafe.com/', 'US', 2006, 1, 0, 0, 0, 0, 0, 'residential', 'mid', 'SimpliSafe Smart Lock — Complete Brand Guide & Review 2026', 'Complete guide to SimpliSafe Smart Lock Series 2. WiFi, PIN pad, integrated with SimpliSafe security system. Review and specs.', NULL, 4, 0, 18, 'published', '2026-02-15 18:55:55', '2026-02-15 18:55:55');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (19, 'Sesame', 'sesame', 'Ultra-compact retrofit smart lock from Japan. Matter support, open-source API, and unbeatable sub-$70 pricing.', 'Sesame (by Candy House) is a Japanese smart lock brand that has redefined what an affordable retrofit smart lock can be. Weighing only 186 grams with dimensions smaller than a deck of cards, the Sesame 5 Pro installs in minutes with 3M adhesive tape over your existing thumbturn — no tools, no drilling, no modifications. Despite its tiny size and sub-$70 price, it offers Matter support (via Hub 3), an open-source Bluetooth API for developers, and a motor rated for 10+ years of use (200 cycles/day). Candy House also offers custom 3D-printed adapters for unusual thumbturn shapes, ensuring near-universal compatibility. The Sesame Touch Pro accessory adds fingerprint and NFC card authentication.', '/images/brands/sesame-logo.png', 'https://candyhouse.co/', 'JP', 2014, 0, 0, 0, 0, 1, 1, 'residential', 'budget', 'Sesame Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Sesame 5 Pro smart lock. Ultra-compact retrofit, Matter, open-source API. Best value at under $70.', NULL, 4.2, 0, 19, 'published', '2026-02-15 18:55:55', '2026-02-15 18:55:55');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (20, 'Brinks', 'brinks', 'Trusted American security brand with solar-powered smart deadbolts and commercial-grade hardware.', 'Brinks, the legendary American security company established in 1859, entered the smart lock market with the Array Smart Deadbolt — featuring an industry-first solar panel that harvests ambient light to extend the rechargeable lithium-polymer battery life to over a year. The Array connects via Wi-Fi for remote access and integrates with Amazon Alexa for voice control. Beyond smart locks, Brinks'' extensive heritage in physical security means their deadbolt mechanisms carry ANSI Grade 2 certification with anti-pick 5-pin cylinders. The PRO-GUARD line adds fingerprint authentication to their electronic deadbolts, combining traditional Brinks security engineering with modern biometric convenience.', '/images/brands/brinks-logo.png', 'https://www.brinkshome.com/', 'US', 1859, 1, 0, 0, 0, 0, 1, 'residential', 'mid', 'Brinks Smart Locks — Complete Brand Guide & Product Reviews 2026', 'Complete guide to Brinks smart locks. Solar-powered Array deadbolt, fingerprint PRO-GUARD series. 160+ years of security heritage.', NULL, 4, 0, 20, 'published', '2026-02-15 18:55:55', '2026-02-15 18:55:55');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (21, 'Hornbill', 'hornbill', 'Amazon bestselling budget smart locks with fingerprint, keypad, and WiFi gateway. Excellent value under $100.', 'Hornbill has emerged as one of the top-selling budget smart lock brands on Amazon, offering a surprisingly feature-rich lineup at prices that undercut major brands by 50-70%. Their locks feature semiconductor fingerprint sensors capable of 0.2-second recognition, illuminated keypads, IC card access, and Bluetooth connectivity — with optional WiFi gateway for remote access and Alexa/Google Home integration. Available in deadbolt, lever, and mortise configurations, Hornbill locks come in multiple series (M-Series, A-Series, Y-Series, H-Series) to cover different door types. While they lack ANSI certification, their zinc alloy construction and 4xAA battery operation deliver reliable performance for budget-conscious homeowners.', '/images/brands/hornbill-logo.png', 'https://www.hornbilllock.com/', 'CN', 2018, 1, 0, 0, 0, 0, 1, 'residential', 'budget', 'Hornbill Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Hornbill smart locks. Budget Amazon bestseller, fingerprint, keypad, WiFi gateway. Best smart lock under $100.', NULL, 4, 0, 21, 'published', '2026-02-15 18:56:03', '2026-02-15 18:56:03');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (22, 'SMONET', 'smonet', 'Handle-style smart locks with fingerprint, keypad, and IC cards. IP65 weatherproof, TTLock app compatible.', 'SMONET specializes in handle-style smart locks that combine a lever handle with electronic access control — making them ideal for replacing traditional lever locksets without adding a separate deadbolt. The ZNS-H001 flagship features a zinc alloy body with IP65 weatherproofing, a semiconductor fingerprint sensor storing up to 250 prints, a touchscreen keypad with anti-peep function, and support for IC cards, mechanical keys, and smartphone Bluetooth. Remote access requires a separate G2 WiFi Gateway. SMONET locks are TTLock/Sciener app compatible and work with Alexa and Google Home, offering premium features at mid-range pricing.', '/images/brands/smonet-logo.png', 'https://www.smonet.com/', 'CN', 2017, 1, 0, 0, 0, 0, 1, 'residential', 'budget', 'SMONET Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to SMONET smart locks. Handle-style, fingerprint, IP65, TTLock app. Best lever handle smart lock for homes.', NULL, 3.9, 0, 22, 'published', '2026-02-15 18:56:03', '2026-02-15 18:56:03');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (23, 'Sifely', 'sifely', 'Versatile smart locks with 6 unlocking methods. Popular for Airbnb hosts with easy code management.', 'Sifely offers both lever and deadbolt smart locks with up to six ways to unlock: fingerprint, keypad, smartphone app, key fob (RFID), physical key, and auto-unlock. Their 3rd/4th generation 3D fingerprint sensors unlock doors in under 0.3 seconds. Sifely locks are particularly popular among short-term rental hosts thanks to easy guest code management through the Sifely app — including timed, recurring, and one-time codes. A separate WiFi Gateway (G2) enables remote access and integration with Alexa and Google Home. Operating on 4 AA batteries lasting up to a year, Sifely locks offer premium features at an accessible price point.', '/images/brands/sifely-logo.png', 'https://www.sifely.com/', 'CN', 2019, 1, 0, 0, 0, 0, 1, 'residential', 'budget', 'Sifely Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Sifely smart locks. 6 unlocking methods, fingerprint, Airbnb-friendly. Best smart lock for rental hosts.', NULL, 4, 0, 23, 'published', '2026-02-15 18:56:03', '2026-02-15 18:56:03');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (24, 'Defiant', 'defiant', 'Home Depot exclusive smart locks powered by Hubspace. Affordable WiFi deadbolts with fingerprint.', 'Defiant is Home Depot''s house brand for residential lock hardware, and their smart lock lineup — "Powered by Hubspace" — brings WiFi connectivity, fingerprint access, and app control to an extremely competitive price point. Defiant smart deadbolts connect to the Hubspace smart home platform, enabling remote lock/unlock, event log viewing, and voice control via Google Assistant and Amazon Alexa. Each WiFi model includes a smart plug that doubles as a WiFi gateway. Available exclusively at Home Depot, Defiant locks are ANSI Grade 3 certified and designed for easy DIY installation on standard US doors.', '/images/brands/defiant-logo.png', 'https://www.homedepot.com/', 'US', 2015, 1, 0, 0, 0, 0, 1, 'residential', 'budget', 'Defiant Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Defiant smart locks at Home Depot. Hubspace WiFi, fingerprint, under $120. Budget smart lock guide.', NULL, 3.8, 0, 24, 'published', '2026-02-15 18:56:03', '2026-02-15 18:56:03');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (25, 'Danalock', 'danalock', 'Danish retrofit smart lock with Z-Wave, Zigbee, and Matter/Thread. Premium European engineering.', 'Danalock is a Danish smart lock company that has built a reputation for premium European retrofit smart locks. The Danalock V3 attaches over your existing thumbturn — no drilling, no door modifications — and supports Z-Wave, Zigbee, and Bluetooth connectivity through swappable radio modules. Compatible with Apple HomeKit, Google Home, and Amazon Alexa, Danalock V3 handles European cylinder locks (DIN standard) and US deadbolts with adapter plates. Their latest developments include Matter/Thread support for the next generation. Danalock''s geofencing auto-lock/unlock, shared access, and auto-calibration make it one of the most polished retrofit solutions in Europe.', '/images/brands/danalock-logo.png', 'https://www.danalock.com/', 'DK', 2013, 0, 1, 1, 1, 1, 1, 'residential', 'mid', 'Danalock Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Danalock. Danish retrofit smart lock, Z-Wave, Zigbee, Matter. Best European retrofit smart lock.', NULL, 4.1, 0, 25, 'published', '2026-02-15 18:56:03', '2026-02-15 18:56:03');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (26, 'Weiser', 'weiser', 'Canadian sister brand of Kwikset with SmartKey security. Halo line with WiFi and fingerprint.', 'Weiser, owned by Spectrum Brands (parent company of Kwikset), is the leading smart lock brand in Canada. Their Halo line mirrors Kwikset''s technology — built-in WiFi, SmartKey re-key technology, and BHMA AAA residential certification — but is marketed and warrantied specifically for the Canadian market. The Weiser Halo Touch brings fingerprint biometrics to a WiFi deadbolt, while the Halo Touchscreen offers keypad entry with up to 250 user codes. Both integrate with the Weiser app, Amazon Alexa, and Google Assistant for remote access and voice control. Weiser also offers traditional electronic deadbolts under the Powerbolt and SmartCode lines.', '/images/brands/weiser-logo.png', 'https://www.weiserlock.com/', 'CA', 1904, 1, 0, 0, 0, 0, 1, 'residential', 'mid', 'Weiser Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Weiser smart locks. Canada''s top lock brand, WiFi Halo, SmartKey security. Best Canadian smart lock.', NULL, 4.2, 0, 26, 'published', '2026-02-15 18:56:03', '2026-02-15 18:56:03');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (27, 'TCL', 'tcl', 'Electronics giant entering smart locks with palm vein recognition and 3D face ID technology.', 'TCL, the global consumer electronics brand known for TVs and smartphones, has expanded into smart home security with an ambitious lineup of smart door locks. TCL locks differentiate with cutting-edge biometric technology including palm vein recognition and 3D structured light facial recognition — technologies borrowed from their mobile device division. Their smart locks feature large touchscreens, built-in WiFi, and integration with the TCL Home app ecosystem. Targeting the premium Asian and European markets, TCL locks combine the brand''s electronics expertise with increasingly competitive smart lock engineering.', '/images/brands/tcl-logo.png', 'https://www.tcl.com/', 'CN', 1981, 1, 0, 0, 0, 0, 1, 'all', 'mid', 'TCL Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to TCL smart locks. Palm vein recognition, 3D facial recognition. Electronics giant meets smart security.', NULL, 3.9, 0, 27, 'published', '2026-02-15 18:56:03', '2026-02-15 18:56:03');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (28, 'Veise', 'veise', 'Amazon #1 bestselling budget fingerprint deadbolt. IP65 weatherproof, 6 unlocking methods, USB-C emergency.', 'Veise has rapidly become one of Amazon''s top-selling smart lock brands, earning the #1 bestseller badge in the deadbolt category. Their locks offer an impressive feature-to-price ratio: semiconductor fingerprint sensors with 0.2-second recognition, illuminated touchscreen keypads with anti-peep codes, IC card (key fob) access, eKey sharing, and mechanical key backup. Models range from Bluetooth-only (VE07, VE017) requiring a separate G1/G2 gateway for WiFi, to built-in WiFi models (VE012W, VE027). Constructed from aluminum and zinc alloy with IP54-IP65 weatherproofing, Veise locks operate in temperatures from -31°F to 158°F. ANSI Grade 3 certified, with USB-C emergency charging port.', '/images/brands/veise-logo.png', 'https://www.iveise.com/', 'CN', 2019, 1, 0, 0, 0, 0, 1, 'residential', 'budget', 'Veise Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Veise smart locks. Amazon #1 bestseller, fingerprint deadbolt, IP65, under $100. Best budget smart lock.', NULL, 4.2, 0, 28, 'published', '2026-02-15 18:56:14', '2026-02-15 18:56:14');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (29, 'Teeho', 'teeho', 'Amazon bestselling keyless deadbolts with fingerprint. Aluminum body, IP54, one-time codes for guests.', 'Teeho burst onto the smart lock scene as Amazon''s bestselling deadbolt brand, anchored by the TE002 — a fingerprint + keypad deadbolt that routinely sells for under $50. Built from aluminum with an IP54 weatherproofing rating, Teeho locks support 20 fingerprints and 20 user codes including one-time temporary codes for guests. The auto-lock timer is adjustable from 10-99 seconds, and the anti-peep password function adds security in shared environments. WiFi-enabled models (TE012W, TE217) bring remote control and Alexa compatibility, while the core TE002 keeps things simple with offline keypad + fingerprint at an unbeatable price. ANSI Grade 3 certified.', '/images/brands/teeho-logo.png', 'https://www.teeho.com/', 'CN', 2020, 1, 0, 0, 0, 0, 1, 'residential', 'budget', 'Teeho Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Teeho smart locks. Amazon bestselling deadbolt, fingerprint, under $50. Best ultra-budget smart lock.', NULL, 4.1, 0, 29, 'published', '2026-02-15 18:56:14', '2026-02-15 18:56:14');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (30, 'HARFO', 'harfo', 'Budget lever handle smart locks with fingerprint, keypad, IC cards. Zinc construction, WiFi via gateway.', 'HARFO produces affordable lever handle smart locks that pack fingerprint, touchscreen keypad, IC card, and mechanical key access into a zinc alloy body. Popular models like the D02H and HF-LM801BK support up to 50 fingerprints, 250 passcodes, and 1000 IC cards. Features include anti-peep password entry, adjustable auto-lock (5-900 seconds), privacy mode, passage mode, and a USB emergency power port. Remote WiFi control requires HARFO''s separately sold WiFi Gateway, which enables Alexa and Google Assistant voice control. Compatible with standard American doors (1 3/8" to 2 3/16" thick), HARFO locks offer solid budget performance.', '/images/brands/harfo-logo.png', 'https://www.harfolock.com/', 'CN', 2018, 1, 0, 0, 0, 0, 1, 'residential', 'budget', 'HARFO Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to HARFO smart locks. Budget lever handle, fingerprint, keypad, IC card. Best budget handle smart lock.', NULL, 3.9, 0, 30, 'published', '2026-02-15 18:56:14', '2026-02-15 18:56:14');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (31, 'Tedee', 'tedee', 'Polish premium retrofit smart lock. Anodized aluminum, rechargeable Li-Po, European cylinder compatible.', 'Tedee is a Polish smart lock company that has established itself as a premium alternative to Nuki in the European retrofit market. The Tedee PRO features an elegant anodized aluminum body (45mm diameter, 196g) with a coreless DC motor that''s whisper-quiet during operation. Powered by a built-in 3000 mAh rechargeable Li-Po battery lasting 6-10 months per overnight charge, Tedee locks attach to European euro profile cylinders. The Tedee Bridge accessory enables remote access, while the optional Tedee Keypad provides code entry without a phone. Available in black, white, silver, and gold finishes, Tedee combines Polish engineering precision with Scandinavian design sensibility.', '/images/brands/tedee-logo.png', 'https://www.tedee.com/', 'PL', 2019, 0, 0, 0, 0, 0, 1, 'residential', 'premium', 'Tedee Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Tedee smart locks. Polish retrofit, aluminum, rechargeable. Premium European smart lock alternative.', NULL, 4.3, 0, 31, 'published', '2026-02-15 18:56:14', '2026-02-15 18:56:14');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (32, 'Kaadas', 'kaadas', 'Premium Asian smart lock brand with 3D face recognition, palm vein, and push-pull handles.', 'Kaadas (凯迪仕) is a leading smart lock brand in Asia, known for pushing the boundaries of biometric access technology. Their product lineup features 3D structured light facial recognition, palm vein scanning, semiconductor fingerprint sensors, and touchscreen keypads — all housed in premium push-pull handle designs. Kaadas locks target the high-security Chinese residential market and have expanded internationally to Southeast Asia, Europe, and the US. Their flagship models include large IPS touchscreen displays, built-in WiFi with cloud connectivity, anti-pry alarms, and lithium-ion rechargeable batteries. Kaadas combines Chinese smart manufacturing expertise with luxury aesthetics.', '/images/brands/kaadas-logo.png', 'https://www.kaadas.com/', 'CN', 2007, 1, 0, 0, 0, 0, 1, 'residential', 'premium', 'Kaadas Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Kaadas smart locks. 3D face recognition, palm vein, push-pull. Premium Asian smart lock brand.', NULL, 4.2, 0, 32, 'published', '2026-02-15 18:56:14', '2026-02-15 18:56:14');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (33, 'Latch', 'latch', 'Enterprise smart access for multifamily buildings. Full-door solution with camera, intercom, and SaaS.', 'Latch revolutionized the commercial smart access market with its full-door, full-building approach to smart locks. Now a part of Dormakaba, Latch offers the Latch M (mortise) and Latch C (cylindrical) smart locks designed specifically for multifamily apartment buildings, offices, and commercial properties. Each lock integrates a camera, intercom, and reader into a single elegant device. Paired with the LatchOS SaaS platform, property managers can remotely manage access, issue temporary keys to guests and delivery personnel, monitor entry activity, and integrate with property management systems. Latch''s cloud-first architecture sets it apart from consumer smart locks.', '/images/brands/latch-logo.png', 'https://www.latch.com/', 'US', 2014, 1, 0, 0, 0, 0, 1, 'commercial', 'premium', 'Latch Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Latch smart access. Enterprise multifamily, camera intercom, LatchOS SaaS. Best commercial smart lock.', NULL, 4, 0, 33, 'published', '2026-02-15 18:56:14', '2026-02-15 18:56:14');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (34, 'Be-Tech', 'be-tech', 'Professional smart lock manufacturer since 1992. Hotel locks, residential digital locks, and commercial access control.', 'BE-TECH is a leading smart lock manufacturer headquartered in Guangzhou, China, founded in 1992. With over 30 years of experience, Be-Tech produces high-quality electronic locks for hotels, residences, and commercial buildings. Their product range spans RFID hotel locks (Visual, Guardian, Shadow, Base series), residential digital locks with fingerprint, RFID, keypad, and WiFi connectivity (via Tuya platform), and electronic cabinet locks. Be-Tech holds certifications from CE, RoHS, BHMA, UL, KC, PSE, and MSAS. Products are manufactured in-house at their large factory facility with rigorous quality inspection processes. Be-Tech serves customers in over 100 countries through their dual-website presence: betechlock.com for hotel/commercial products and betechiot.com for residential IoT smart locks.', '/images/brands/be-tech-logo.png', 'https://www.betechlock.com/', 'CN', 1992, 1, 0, 0, 0, 0, 1, 'commercial', 'mid', 'Be-Tech Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Be-Tech smart locks. Since 1992, hotel RFID locks, residential fingerprint locks, WiFi via Tuya. Professional smart lock manufacturer.', NULL, 4.1, 1, 34, 'published', '2026-02-26 21:53:19', '2026-02-26 21:53:19');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (35, 'Dessmann', 'dessmann', 'German-designed smart locks with fingerprint, face recognition, and cat-eye camera. Top 3 smart lock brand in China.', 'Dessmann (德施曼, Dessmann Schliessanlagen GmbH) is a smart lock brand founded with German engineering heritage and manufactured in China. Established as a company in 2003, Dessmann has grown to become one of the top 3 smart lock brands in the Chinese residential market. Their product range includes push-pull mortise locks with 3D face recognition and smart cat-eye cameras (Q5M series), touch-screen fingerprint mortise locks with sliding keypad covers (S510 series), and elegant fingerprint lever locks (G810 series). Dessmann locks undergo 36 strict quality control processes and feature German-standard engineering with materials including tempered glass, zinc alloy, and aluminum alloy bodies. Their advanced models offer WiFi connectivity for remote access, dual lithium battery systems for extended battery life, and 1080p night vision cat-eye cameras for doorstep monitoring.', '/images/brands/dessmann-logo.png', 'https://www.dessmannlock.com/', 'DE', 2003, 1, 0, 0, 0, 0, 1, 'residential', 'premium', 'Dessmann Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Dessmann smart locks. German design, 3D face recognition, cat-eye camera. Top 3 China smart lock brand.', NULL, 4.2, 0, 35, 'published', '2026-02-26 21:53:19', '2026-02-26 21:53:19');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (36, 'ZKTeco', 'zkteco', 'Global biometrics and access control leader. Fingerprint, facial recognition, and multi-biometric smart locks.', 'ZKTeco is a leading global biometrics and intelligent security manufacturer founded in 1998 in Dongguan, China. With operations in over 180 countries, ZKTeco is one of the world''s largest biometric access control companies. Their smart lock lineup includes advanced models with 3D structured light facial recognition (HBL400), fully automatic locks with indoor LCD monitoring screens and WiFi connectivity (TL800), commercial-grade fingerprint locks supporting up to 500 fingerprints and 30,000 access logs (L5000), and Zigbee-enabled fingerprint locks for smart home integration (TL300Z). ZKTeco locks are built with aluminum alloy and tempered glass materials, feature lithium rechargeable batteries, and integrate with the ZSmart mobile app and ZKBio CVSecurity platform for comprehensive access management. The brand is particularly strong in biometric technology, holding numerous patents in fingerprint and facial recognition algorithms.', '/images/brands/zkteco-logo.png', 'https://www.zkteco.com/', 'CN', 1998, 1, 0, 0, 0, 0, 1, 'commercial', 'mid', 'ZKTeco Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to ZKTeco smart locks. Global biometrics leader, face recognition, 180+ countries. Professional access control smart locks.', NULL, 4, 0, 36, 'published', '2026-02-26 21:53:19', '2026-02-26 21:53:19');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (37, 'Xiaomi', 'xiaomi', 'World''s largest IoT platform with smart locks featuring 3D face recognition, palm vein scanning, and cat-eye cameras.', 'Xiaomi is one of the world''s largest consumer electronics and IoT platform companies, founded in 2010 in Beijing, China. Their smart lock division produces advanced residential locks featuring 3D structured light facial recognition, AI palm vein scanning, fingerprint sensors with 99.51% accuracy, and built-in peephole cameras with AI human detection. Xiaomi smart locks integrate seamlessly with the Mi Home/HyperOS ecosystem supporting WiFi and Bluetooth connectivity. Their global Self-Install Smart Lock supports Matter standard for Apple Home, Google Home, and Alexa compatibility. Models range from the budget-friendly Smart Door Lock 2 Cat Eye Edition to the premium Smart Door Lock 4 Pro with 12 unlocking methods. All locks feature C-grade lock cylinders, 5000mAh lithium batteries with AA backup, and USB-C emergency charging.', '/images/brands/xiaomi-logo.png', 'https://www.mi.com/', 'CN', 2010, 1, 0, 0, 0, 1, 1, 'residential', 'mid', 'Xiaomi Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Xiaomi smart locks. 3D face recognition, palm vein, Matter support, Mi Home ecosystem. Best value smart locks.', NULL, 4.3, 1, 37, 'published', '2026-02-26 22:40:16', '2026-02-26 22:40:16');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (38, 'SALTO', 'salto', 'Spanish access control pioneer with cloud-based Homelok ecosystem, DLok retrofit lock, and XS4 commercial platform.', 'SALTO Systems is a global leader in electronic access control solutions, founded in 2001 in the Basque Country, Spain. SALTO serves over 30,000 customers in more than 90 countries. Their product portfolio spans residential (Homelok ecosystem with DLok smart lock) and commercial (XS4 platform) markets. The DLok is a minimalist retrofit smart lock weighing just 230g with anodized aluminum construction, designed for existing deadbolts with under-15-minute installation. SALTO''s cloud-based Homelok platform enables keyless access via smartphone app, Apple Wallet digital keys, and remote management. The XS4 platform supports Mifare/DESfire, HID iClass, NFC, Bluetooth LE, and BLUEnet wireless technology. All SALTO products use AES 128-bit encryption and integrate with the SALTO Virtual Network (SVN) for offline data management.', '/images/brands/salto-logo.png', 'https://www.saltosystems.com/', 'ES', 2001, 1, 0, 0, 0, 0, 1, 'commercial', 'premium', 'SALTO Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to SALTO smart locks. Spanish access control, DLok retrofit, Homelok cloud, XS4 platform. Best commercial access control.', NULL, 4.4, 0, 38, 'published', '2026-02-26 22:40:16', '2026-02-26 22:40:16');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (39, 'Godrej', 'godrej', 'India''s most trusted lock brand since 1897. Smart locks with military-grade encryption, dual authentication, and Alexa integration.', 'Godrej is India''s most iconic and trusted security brand, part of the Godrej Group established in 1897. Their smart lock division produces digital door locks featuring military-grade encryption, dual authentication, 360-degree fingerprint recognition, anti-prank alarms, and privacy lockout functions. Product lines include the Catus series (budget-friendly 4-in-1 access), Advantis series (premium 7-9 access modes with WiFi, NFC, and smart assistant integration), and the new Neo range with built-in video door phones. Godrej smart locks are designed for Indian market conditions with special weatherproofing, support for wooden doors (35-65mm thickness), and emergency power backup via 9V battery. The Advantis IOT9 flagship supports 9 access modes and integrates with Amazon Alexa and Google Assistant for voice control.', '/images/brands/godrej-logo.png', 'https://www.godrejenterprises.com/', 'IN', 1897, 1, 0, 0, 0, 0, 1, 'residential', 'mid', 'Godrej Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Godrej smart locks. India''s #1 lock brand, military-grade encryption, 9 access modes. Best smart lock in India.', NULL, 4.1, 0, 39, 'published', '2026-02-26 22:40:16', '2026-02-26 22:40:16');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (40, 'EPIC', 'epic', 'Korean digital lock pioneer since 1989. Facial recognition, gate-door link, and EPIC Things app for remote control.', 'EPIC Systems Co., Ltd. is a prominent South Korean digital door lock manufacturer founded in 1989. As one of Korea''s earliest and most established smart lock brands, EPIC produces advanced digital locks for residential, commercial, and hospitality markets. Their product lineup includes the flagship 8G series with 3D facial recognition (up to 30 faces), the 5G series with fingerprint and Bluetooth, the 6G Pro for metal gates with gate-door link technology, and various mortise lock models. EPIC locks feature the EPIC Things smartphone app for remote control, guest key sharing, access logs, and push notifications. Security features include random number entry, dual authentication, anti-prank alarms (auto-disable after failed attempts), and fire detection alarms. All models support multiple access methods including fingerprint (up to 100), RFID cards (up to 200), PIN codes, and mechanical keys.', '/images/brands/epic-logo.png', 'https://www.epic.co.kr/', 'KR', 1989, 0, 0, 0, 0, 0, 1, 'residential', 'mid', 'EPIC Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to EPIC smart locks. Korean pioneer since 1989, facial recognition, gate-door link. Best Korean digital door lock.', NULL, 4.2, 0, 40, 'published', '2026-02-26 22:40:16', '2026-02-26 22:40:16');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (41, 'Häfele', 'hafele', 'German furniture fittings giant with premium digital locks. Fire-rated push-pull locks with FBI-approved SILK ID fingerprint scanning.', 'Häfele is a German international company founded in 1923 in Nagold, specializing in furniture fittings, architectural hardware, and electronic access solutions. With operations in over 150 countries, Häfele has become a major digital lock brand particularly strong in Singapore, India, and Southeast Asian markets. Their digital lock range includes the fire-rated PP8100 push-pull lock, the DL7600 lever handle lock, and the RE-Twist series with integrated doorbell. Häfele locks feature advanced security including FBI-approved SILK ID fingerprint scanning (works on dry/wet/oily fingers), random security code function, privacy locking mode, away/defense mode, and electric shock resistance. Optional Z-Wave modules enable smart home integration. Product quality adheres to strict German engineering standards with fire ratings up to 60 minutes on select models.', '/images/brands/hafele-logo.png', 'https://www.hafele.com/', 'DE', 1923, 0, 0, 1, 0, 0, 1, 'residential', 'premium', 'Häfele Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Häfele digital locks. German engineering, FBI SILK ID fingerprint, fire-rated. Best premium smart lock in Asia.', NULL, 4.2, 0, 41, 'published', '2026-02-26 22:53:09', '2026-02-26 22:53:09');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (42, 'Solity', 'solity', 'Korea''s #1 digital door lock brand. Push-pull innovator with facial recognition, Matter standard, and Samsung SDS co-developed technology.', 'Solity is Korea''s number one digital door lock brand and a global access solution provider. The company pioneered push-pull door locks in Korea through a joint R&D effort with Samsung SDS. Solity produces a comprehensive range of smart locks including push-pull, mortise, mini-mortise, rim, glass door, and sash lock types. Their flagship GP-6000 features facial recognition (100 users), push-pull ergonomic design with fingerprint built into the handle, and WiFi connectivity. The newer G1 gate lock is Matter-ready, supporting Apple HomeKit, Google Home, Amazon Alexa, and SmartThings. Solity maintains rigorous quality with over 50 reliability tests before mass production, meeting global standards including KC, GA374, EN1906, ANSI A156.25, UL437, and UL10B/10C certifications. Products are developed with in-house R&D in Korea.', '/images/brands/solity-logo.png', 'https://www.solitykorea.com/', 'KR', 2014, 1, 0, 0, 0, 1, 1, 'residential', 'mid', 'Solity Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Solity. Korea #1 digital lock, facial recognition, Matter/HomeKit/Alexa. Best Korean smart lock brand.', NULL, 4.3, 0, 42, 'published', '2026-02-26 22:53:09', '2026-02-26 22:53:09');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (43, 'Mul-T-Lock', 'mul-t-lock', 'Israeli high-security pioneer under ASSA ABLOY. ENTR retrofit smart lock with app, fingerprint, and patented cylinder technology.', 'Mul-T-Lock is an Israeli high-security lock manufacturer founded in 1973, now part of the ASSA ABLOY Group, the world''s largest lock company. Known for their patented Interactive+ and MT5+ cylinder platforms used worldwide by governments and embassies, Mul-T-Lock entered the smart lock space with the ENTR system. The ENTR is a retrofit smart lock that installs on existing doors without drilling or wiring, transforming any door into a smart entry point. It supports smartphone app control (iOS/Android), fingerprint reader (20 users), PIN code reader (20 codes), and remote control (20 remotes). The ENTR uses AES-128 encryption, rechargeable Li-ion battery (7.4V 2600mAh), and IP44 weather protection. The Code-It electronic handle provides keyless interior applications with 9 personal codes and 100,000-cycle battery life.', '/images/brands/mul-t-lock-logo.png', 'https://www.mul-t-lock.com/', 'IL', 1973, 0, 0, 0, 0, 0, 1, 'residential', 'premium', 'Mul-T-Lock Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Mul-T-Lock. Israeli high-security, ASSA ABLOY, ENTR retrofit, patented cylinders. Best security-focused smart lock.', NULL, 4.3, 0, 43, 'published', '2026-02-26 22:53:09', '2026-02-26 22:53:09');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (44, 'Qrio', 'qrio', 'Japanese smart lock brand. Ultra-lightweight retrofit with 600-day battery, hands-free unlock, and Apple Watch support.', 'Qrio is a Japanese smart home technology company that produces the Qrio Lock (Q-SL2), one of Japan''s most popular smart locks. The Qrio Lock is an ultra-lightweight (207g) retrofit device that attaches to existing door locks using double-sided tape — no drilling, no wiring, perfect for rental properties. It connects via Bluetooth Low Energy and uses public key cryptography for security. With 2x CR123A batteries, it achieves an impressive 600-day battery life at 10 operations per day. Key features include hands-free auto-unlock (detects approaching smartphone), auto-lock with magnetic door sensor, digital key sharing, and Apple Watch support. The ecosystem includes Qrio Hub (WiFi bridge for remote access), Qrio Pad (IC card + PIN keypad), and Qrio Key S (physical remote). Compatible with Amazon Alexa and Google Assistant via Qrio Hub.', '/images/brands/qrio-logo.png', 'https://qrio.me/', 'JP', 2014, 0, 0, 0, 0, 0, 1, 'residential', 'mid', 'Qrio Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Qrio. Japanese retrofit smart lock, 207g, 600-day battery, Apple Watch. Best smart lock in Japan.', NULL, 4.2, 0, 44, 'published', '2026-02-26 23:01:33', '2026-02-26 23:01:33');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (45, 'PHGLock', 'phglock', 'Australian smart lock brand popular in Vietnam. Fingerprint, facial recognition, and hotel card locks for Southeast Asian markets.', 'PHGLock is an Australian smart lock brand with strong presence in Vietnam and Southeast Asia, exclusively distributed by Green Universe Joint Stock Company. Their product range covers residential, commercial, and hotel applications. PHGLock produces fingerprint locks (FP series), keypad locks, RFID card locks (KR series for apartments), facial recognition locks, and hotel card lock systems. Their locks feature 4.0 security technology with anti-prying mechanisms, anti-code detection, and intrusion alarms. Products are built with high-grade aluminum alloy and stainless steel for durability. The lineup includes specialized models for narrow-stile aluminum doors (FP5208B), apartment card locks (KR8161), office glass door locks (FG3605), and handle-fingerprint models (FP8003). Battery-powered with AAA batteries, 6-12 month lifespan, USB emergency power.', '/images/brands/phglock-logo.png', 'https://phglock.vn/', 'AU', 2010, 0, 0, 0, 0, 0, 1, 'residential', 'budget', 'PHGLock Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to PHGLock. Australian brand in Vietnam, fingerprint, facial recognition. Best affordable smart lock in Southeast Asia.', NULL, 3.9, 0, 45, 'published', '2026-02-26 23:01:33', '2026-02-26 23:01:33');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (46, 'Orbita', 'orbita', 'Chinese hotel lock specialist with 800,000-cycle BHMA testing and 180-minute UL fire rating. RFID, BLE, and PMS integration.', 'Orbita is a professional hospitality technology manufacturer based in China with a 46,000 sqm factory and ISO certifications. Specializing in hotel locking systems, Orbita produces RFID hotel locks, Bluetooth-enabled hotel locks, hotel safes, and energy-saving switches. Their hotel locks are constructed from 304 stainless steel and zinc alloy, designed for 10+ year corrosion resistance. Orbita products pass 800,000-cycle BHMA standard testing and 180-minute UL fire tests — among the highest in the industry. All locks support Mifare 13.56MHz RFID/NFC technology with optional Bluetooth and wireless online solutions. They interface with most Property Management Systems (PMS) including Opera/FIAS formats. Products hold UL, FCC, RoHS, CE, SASO, and SIRIM certifications.', '/images/brands/orbita-logo.png', 'https://www.orbitatech.com/', 'CN', 2003, 0, 0, 0, 0, 0, 1, 'commercial', 'mid', 'Orbita Hotel Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Orbita. Hotel RFID locks, 800K BHMA cycles, UL fire rated, PMS integration. Best value hotel lock system.', NULL, 4.1, 0, 46, 'published', '2026-02-26 23:01:33', '2026-02-26 23:01:33');
INSERT INTO "brands" ("id", "name", "slug", "description", "long_description", "logo_url", "website_url", "country", "founded_year", "supports_wifi", "supports_zigbee", "supports_zwave", "supports_thread", "supports_matter", "supports_bluetooth", "target_market", "price_tier", "meta_title", "meta_description", "og_image_url", "rating", "featured", "display_order", "status", "created_at", "updated_at") VALUES (47, 'Orvibo', 'orvibo', 'Chinese smart home brand with ZigBee and WiFi smart locks. AI fingerprint recognition, smart scene linkage via HomeMate App.', 'Orvibo is a Chinese smart home ecosystem company specializing in IoT devices including smart locks, switches, sensors, and home automation systems. Their smart lock lineup features the C1 with AI fingerprint recognition, EMP protection, and WiFi/NFC access; the S2 with German C-Class copper lock cylinder, 2.5-year battery life, and 8 security sensors; and the V5 with AI binocular face recognition. Orvibo locks integrate with the HomeMate App for real-time monitoring, smart scene linkage (auto-trigger lights/curtains on door open), and remote management. The L10HT model uses ZigBee HA protocol for low-power smart home mesh integration. All locks feature financial-grade encryption chips, anti-pry stainless steel bodies, and USB-C emergency power. Orvibo products are sold globally through their smart home platform.', '/images/brands/orvibo-logo.png', 'https://www.orvibo.com/', 'CN', 2011, 1, 1, 0, 0, 0, 1, 'residential', 'mid', 'Orvibo Smart Locks — Complete Brand Guide & Reviews 2026', 'Complete guide to Orvibo. ZigBee/WiFi, AI fingerprint, 2.5yr battery, HomeMate. Best Chinese smart home lock.', NULL, 4, 0, 47, 'published', '2026-02-26 23:01:33', '2026-02-26 23:01:33');
